//! [`wide`] vector types as [`Simd`] backends.
//!
//! `wide` is pure Rust over `safe_arch`, so enabling the backend adds no C
//! and no build script. On x86-64 with AVX-512 its `f64x8` is a native
//! `__m512d` and its `f32x16` a native `__m512`; without it, `wide` composes
//! narrower registers, and the kernels are unaffected either way.
//!
//! The six widths — three per precision, at 128, 256 and 512 bits — are
//! generated by one macro because their APIs are identical, which is the
//! point: adding a width is a single line, not another copy of every kernel.

use super::{Mask, Simd};

macro_rules! impl_wide {
    ($vec:ty, $elem:ty, $uint:ty, $lanes:literal, $wide:ty $(, $extra:item)*) => {
        impl Mask for MaskOf<$vec> {
            const LANES: usize = $lanes;
            type Bools = [bool; $lanes];

            #[inline(always)]
            fn any(self) -> bool {
                self.0.any()
            }
            #[inline(always)]
            fn all(self) -> bool {
                self.0.all()
            }
            #[inline(always)]
            fn and(self, other: Self) -> Self {
                MaskOf(self.0 & other.0)
            }
            #[inline(always)]
            fn or(self, other: Self) -> Self {
                MaskOf(self.0 | other.0)
            }
            #[inline(always)]
            fn not(self) -> Self {
                // A `wide` comparison yields all-ones or all-zeros per lane,
                // so negation is a select between those two patterns. Done
                // this way rather than with `!`, which `wide` does not provide
                // for float vectors.
                MaskOf(self.0.select(<$vec>::ZERO, ALL_ONES_.0))
            }
            #[inline(always)]
            fn to_bools(self) -> Self::Bools {
                let lanes: [$elem; $lanes] = self.0.into();
                lanes.map(|v| v.to_bits() != 0)
            }
            #[inline(always)]
            fn to_bitmask(self) -> u32 {
                let bools = self.to_bools();
                let mut mask = 0u32;
                for i in 0..$lanes {
                    if bools[i] {
                        mask |= 1 << i;
                    }
                }
                mask
            }
        }

        impl Simd for $vec {
            type Elem = $elem;
            const LANES: usize = $lanes;
            type Mask = MaskOf<$vec>;
            type Floats = [$elem; $lanes];
            type Bits = [$uint; $lanes];
            type Bools = [bool; $lanes];
            type Wide = $wide;

            #[inline(always)]
            fn widen(self) -> $wide {
                // Via the lane array rather than a dedicated intrinsic: `wide`
                // exposes no widening conversion, and this lowers to the same
                // single `cvtps2pd` — the loop is fixed-length and every lane
                // is independent.
                let lanes: [$elem; $lanes] = self.into();
                <$wide>::new(lanes.map(|v| v as f64))
            }
            #[inline(always)]
            fn narrow(wide: $wide) -> Self {
                let lanes: [f64; $lanes] = wide.into();
                <$vec>::new(lanes.map(|v| v as $elem))
            }

            #[inline(always)]
            fn splat(v: $elem) -> Self {
                <$vec>::splat(v)
            }
            #[inline(always)]
            fn to_array(self) -> Self::Floats {
                self.into()
            }
            #[inline(always)]
            fn from_array(a: Self::Floats) -> Self {
                <$vec>::new(a)
            }
            #[inline(always)]
            fn to_bits(self) -> Self::Bits {
                let lanes: [$elem; $lanes] = self.into();
                lanes.map(<$elem>::to_bits)
            }
            #[inline(always)]
            fn from_bits(b: Self::Bits) -> Self {
                <$vec>::new(b.map(<$elem>::from_bits))
            }

            #[inline(always)]
            fn mul_add(self, mul: Self, add: Self) -> Self {
                // `wide` silently degrades `mul_add` to `self * mul + add`
                // when the target has no FMA — two roundings where the
                // contract requires one. That is not a small difference: it
                // costs bit-exactness on roughly one input in two thousand,
                // which is precisely the kind of failure that survives casual
                // testing. Fall back to a genuine per-lane FMA instead, which
                // is slower but correct; build with `-C target-cpu=native` (or
                // `-C target-feature=+fma`) to get the vector instruction.
                #[cfg(target_feature = "fma")]
                {
                    <$vec>::mul_add(self, mul, add)
                }
                #[cfg(not(target_feature = "fma"))]
                {
                    let a: [$elem; $lanes] = self.into();
                    let b: [$elem; $lanes] = mul.into();
                    let c: [$elem; $lanes] = add.into();
                    let mut out = [0.0 as $elem; $lanes];
                    for i in 0..$lanes {
                        out[i] = a[i].mul_add(b[i], c[i]);
                    }
                    <$vec>::new(out)
                }
            }
            #[inline(always)]
            fn abs(self) -> Self {
                <$vec>::abs(self)
            }
            #[inline(always)]
            fn sqrt(self) -> Self {
                <$vec>::sqrt(self)
            }

            #[inline(always)]
            fn floor(self) -> Self {
                <$vec>::floor(self)
            }
            #[inline(always)]
            fn ceil(self) -> Self {
                <$vec>::ceil(self)
            }
            #[inline(always)]
            fn trunc(self) -> Self {
                <$vec>::trunc(self)
            }
            #[inline(always)]
            fn round_ties_even(self) -> Self {
                <$vec>::round_ties_even(self)
            }

            #[inline(always)]
            fn and_bits(self, other: Self) -> Self {
                self & other
            }
            #[inline(always)]
            fn or_bits(self, other: Self) -> Self {
                self | other
            }
            #[inline(always)]
            fn xor_bits(self, other: Self) -> Self {
                self ^ other
            }

            #[inline(always)]
            fn lt_mask(self, other: Self) -> Self::Mask {
                MaskOf(self.simd_lt(other))
            }
            #[inline(always)]
            fn le_mask(self, other: Self) -> Self::Mask {
                MaskOf(self.simd_le(other))
            }
            #[inline(always)]
            fn gt_mask(self, other: Self) -> Self::Mask {
                MaskOf(self.simd_gt(other))
            }
            #[inline(always)]
            fn ge_mask(self, other: Self) -> Self::Mask {
                MaskOf(self.simd_ge(other))
            }
            #[inline(always)]
            fn eq_mask(self, other: Self) -> Self::Mask {
                MaskOf(self.simd_eq(other))
            }

            #[inline(always)]
            fn select(mask: Self::Mask, if_true: Self, if_false: Self) -> Self {
                mask.0.select(if_true, if_false)
            }

            $($extra)*
        }
    };
}

/// A comparison result.
///
/// A newtype rather than the bare vector: in `wide` a mask *is* an `fNxM`
/// whose lanes are all-ones or all-zeros, so without this the `Mask` and
/// `Simd` impls would collide on the same type.
#[derive(Clone, Copy, Debug)]
pub struct MaskOf<V>(pub V);

macro_rules! all_ones {
    ($vec:ty, $elem:ty, $uint:ty, $lanes:literal) => {
        const ALL_ONES_: MaskOf<$vec> =
            MaskOf(<$vec>::new([<$elem>::from_bits(<$uint>::MAX); $lanes]));
    };
}

macro_rules! backend {
    ($modname:ident, $vec:ident, $elem:ty, $uint:ty, $lanes:literal, $wide:ident) => {
        mod $modname {
            use super::*;
            use wide::{$vec, $wide};
            all_ones!($vec, $elem, $uint, $lanes);
            impl_wide!($vec, $elem, $uint, $lanes, $wide);
        }
    };
    // A double-precision width is its own widening.
    ($modname:ident, $vec:ident, $lanes:literal) => {
        mod $modname {
            use super::*;
            use wide::$vec;
            all_ones!($vec, f64, u64, $lanes);
            impl_wide!($vec, f64, u64, $lanes, $vec);
        }
    };
    // A double-precision width, with hardware gather overrides.
    ($modname:ident, $vec:ident, $lanes:literal, gather: $($extra:item)+) => {
        mod $modname {
            use super::*;
            use wide::$vec;
            all_ones!($vec, f64, u64, $lanes);
            impl_wide!($vec, f64, u64, $lanes, $vec $(, $extra)+);
        }
    };
}

backend!(d2, f64x2, 2);
backend!(
    d4,
    f64x4,
    4,
    gather:
        /// `AVX2` hardware gather — see `Simd::gather_bits`'s doc for the
        /// contract and `ROADMAP.md`'s A5 for the measurement that gates
        /// using it. The default per-lane loop remains the fallback on every
        /// target without `avx2`, and is what a debug build (or a build
        /// without `-C target-cpu=native`/`+avx2`) actually runs.
        #[allow(unsafe_code)]
        #[inline(always)]
        unsafe fn gather_bits(table: &[u64], idx: [u64; 4]) -> [u64; 4] {
            #[cfg(all(target_arch = "x86_64", target_feature = "avx2"))]
            {
                use core::arch::x86_64::{_mm256_i64gather_epi64, _mm256_set_epi64x};
                // SAFETY: forwarded from the caller's own contract (every
                // `idx[i] < table.len()`) — see `Simd::gather_bits`.
                unsafe {
                    let vidx =
                        _mm256_set_epi64x(idx[3] as i64, idx[2] as i64, idx[1] as i64, idx[0] as i64);
                    let gathered = _mm256_i64gather_epi64(table.as_ptr().cast(), vidx, 8);
                    core::mem::transmute::<core::arch::x86_64::__m256i, [u64; 4]>(gathered)
                }
            }
            #[cfg(not(all(target_arch = "x86_64", target_feature = "avx2")))]
            {
                let mut out = [0u64; 4];
                for i in 0..4 {
                    out[i] = table[idx[i] as usize];
                }
                out
            }
        }
);
backend!(
    d8,
    f64x8,
    8,
    gather:
        /// `AVX-512F` hardware gather — see `Simd::gather_bits`'s doc for the
        /// contract and `ROADMAP.md`'s A5 for the measurement that gates
        /// using it.
        #[allow(unsafe_code)]
        #[inline(always)]
        unsafe fn gather_bits(table: &[u64], idx: [u64; 8]) -> [u64; 8] {
            #[cfg(all(target_arch = "x86_64", target_feature = "avx512f"))]
            {
                use core::arch::x86_64::{_mm512_i64gather_epi64, _mm512_set_epi64};
                // SAFETY: forwarded from the caller's own contract (every
                // `idx[i] < table.len()`) — see `Simd::gather_bits`.
                unsafe {
                    let vidx = _mm512_set_epi64(
                        idx[7] as i64,
                        idx[6] as i64,
                        idx[5] as i64,
                        idx[4] as i64,
                        idx[3] as i64,
                        idx[2] as i64,
                        idx[1] as i64,
                        idx[0] as i64,
                    );
                    let gathered = _mm512_i64gather_epi64(vidx, table.as_ptr().cast(), 8);
                    core::mem::transmute::<core::arch::x86_64::__m512i, [u64; 8]>(gathered)
                }
            }
            #[cfg(not(all(target_arch = "x86_64", target_feature = "avx512f")))]
            {
                let mut out = [0u64; 8];
                for i in 0..8 {
                    out[i] = table[idx[i] as usize];
                }
                out
            }
        }

        /// `AVX-512F` block-load-and-transpose — see `Simd::gather_run`'s doc
        /// for what it is for and its safety contract.
        ///
        /// Eight lanes each want the same `N` adjacent slots of their own row.
        /// Read element by element that is `8 * N` scalar loads, each of which
        /// also costs a merge into its half-register; read *row* by row it is
        /// one 512-bit load per lane and then a transpose, which is
        /// three stages of eight in-register shuffles and no loads at all
        /// beyond the eight. For `asin`'s twelve-slot rows that trades 96
        /// loads and 84 merge/insert operations for 16 loads and 44 shuffles.
        ///
        /// `N > 8` needs a second block; only the columns actually asked for
        /// are built from it, so `N = 12` costs 24 shuffles for the first
        /// block and 20 for the second rather than 48.
        #[allow(unsafe_code)]
        #[inline(always)]
        unsafe fn gather_run<const N: usize>(table: &[u64], idx: [u64; 8]) -> [f64x8; N] {
            #[cfg(all(target_arch = "x86_64", target_feature = "avx512f"))]
            {
                if N > 2 && N <= 16 {
                    // SAFETY: forwarded from the caller's own contract, in the
                    // block-rounded form `Simd::gather_run` states: each block
                    // load reads eight slots from `idx[i]` or `idx[i] + 8`,
                    // and `N > 8` is what gates the second one.
                    let cols = unsafe { transpose_blocks::<N>(table, idx) };
                    return core::array::from_fn(|j| {
                        <f64x8 as Simd>::from_bits(cols[j])
                    });
                }
            }
            let mut out = [[0u64; 8]; N];
            for i in 0..8 {
                let base = idx[i] as usize;
                for j in 0..N {
                    out[j][i] = table[base + j];
                }
            }
            out.map(<f64x8 as Simd>::from_bits)
        }
);

/// The 8x8 double transpose behind `f64x8`'s `Simd::gather_run` override.
///
/// Returns sixteen columns' worth of storage but only fills the `N` the
/// caller asked for: the first block always costs a full 8x8 transpose
/// (24 shuffles), and a second block, when `N > 8`, costs only the stages
/// leading to its first `N - 8` columns.
///
/// # Safety
/// `table.len()` must be at least `idx[i] + 8` for every lane, and at least
/// `idx[i] + 16` when `N > 8`.
#[cfg(all(target_arch = "x86_64", target_feature = "avx512f"))]
#[allow(unsafe_code)]
#[inline(always)]
unsafe fn transpose_blocks<const N: usize>(table: &[u64], idx: [u64; 8]) -> [[u64; 8]; N] {
    use core::arch::x86_64::{
        __m512d, _mm512_loadu_pd, _mm512_shuffle_f64x2, _mm512_unpackhi_pd, _mm512_unpacklo_pd,
    };

    /// One block: eight rows in, up to eight columns out.
    ///
    /// Stage 1 interleaves adjacent rows within each 128-bit lane, stages 2
    /// and 3 shuffle those 128-bit lanes into place; `0x88` takes the even
    /// lanes of both sources and `0xdd` the odd ones, which is exactly the
    /// even/odd column split each stage needs.
    #[inline(always)]
    fn columns(r: [__m512d; 8], want: usize) -> [__m512d; 8] {
        // SAFETY: pure register shuffles, no memory operand; `avx512f` is a
        // static target feature here.
        unsafe {
            let t0 = _mm512_unpacklo_pd(r[0], r[1]);
            let t1 = _mm512_unpackhi_pd(r[0], r[1]);
            let t2 = _mm512_unpacklo_pd(r[2], r[3]);
            let t3 = _mm512_unpackhi_pd(r[2], r[3]);
            let t4 = _mm512_unpacklo_pd(r[4], r[5]);
            let t5 = _mm512_unpackhi_pd(r[4], r[5]);
            let t6 = _mm512_unpacklo_pd(r[6], r[7]);
            let t7 = _mm512_unpackhi_pd(r[6], r[7]);

            let s0 = _mm512_shuffle_f64x2(t0, t2, 0x88);
            let s4 = _mm512_shuffle_f64x2(t4, t6, 0x88);
            let c0 = _mm512_shuffle_f64x2(s0, s4, 0x88);
            let mut out = [c0; 8];
            if want > 1 {
                let s1 = _mm512_shuffle_f64x2(t1, t3, 0x88);
                let s5 = _mm512_shuffle_f64x2(t5, t7, 0x88);
                out[1] = _mm512_shuffle_f64x2(s1, s5, 0x88);
                if want > 5 {
                    out[5] = _mm512_shuffle_f64x2(s1, s5, 0xdd);
                }
            }
            if want > 2 {
                let s2 = _mm512_shuffle_f64x2(t0, t2, 0xdd);
                let s6 = _mm512_shuffle_f64x2(t4, t6, 0xdd);
                out[2] = _mm512_shuffle_f64x2(s2, s6, 0x88);
                if want > 6 {
                    out[6] = _mm512_shuffle_f64x2(s2, s6, 0xdd);
                }
            }
            if want > 3 {
                let s3 = _mm512_shuffle_f64x2(t1, t3, 0xdd);
                let s7 = _mm512_shuffle_f64x2(t5, t7, 0xdd);
                out[3] = _mm512_shuffle_f64x2(s3, s7, 0x88);
                if want > 7 {
                    out[7] = _mm512_shuffle_f64x2(s3, s7, 0xdd);
                }
            }
            if want > 4 {
                out[4] = _mm512_shuffle_f64x2(s0, s4, 0xdd);
            }
            out
        }
    }

    // SAFETY: the caller guarantees every block load is in bounds.
    unsafe {
        let p = table.as_ptr().cast::<f64>();
        let lo = columns(
            [
                _mm512_loadu_pd(p.add(idx[0] as usize)),
                _mm512_loadu_pd(p.add(idx[1] as usize)),
                _mm512_loadu_pd(p.add(idx[2] as usize)),
                _mm512_loadu_pd(p.add(idx[3] as usize)),
                _mm512_loadu_pd(p.add(idx[4] as usize)),
                _mm512_loadu_pd(p.add(idx[5] as usize)),
                _mm512_loadu_pd(p.add(idx[6] as usize)),
                _mm512_loadu_pd(p.add(idx[7] as usize)),
            ],
            if N < 8 { N } else { 8 },
        );
        let hi = if N > 8 {
            columns(
                [
                    _mm512_loadu_pd(p.add(idx[0] as usize + 8)),
                    _mm512_loadu_pd(p.add(idx[1] as usize + 8)),
                    _mm512_loadu_pd(p.add(idx[2] as usize + 8)),
                    _mm512_loadu_pd(p.add(idx[3] as usize + 8)),
                    _mm512_loadu_pd(p.add(idx[4] as usize + 8)),
                    _mm512_loadu_pd(p.add(idx[5] as usize + 8)),
                    _mm512_loadu_pd(p.add(idx[6] as usize + 8)),
                    _mm512_loadu_pd(p.add(idx[7] as usize + 8)),
                ],
                N - 8,
            )
        } else {
            lo
        };
        core::array::from_fn(|j| {
            let v = if j < 8 { lo[j] } else { hi[j - 8] };
            core::mem::transmute::<__m512d, [u64; 8]>(v)
        })
    }
}

backend!(s4, f32x4, f32, u32, 4, f64x4);
backend!(s8, f32x8, f32, u32, 8, f64x8);

// `f32x16` is deliberately absent. Every single-precision kernel that has to
// be bit-exact replays the platform routine's *double-precision* schedule —
// that is what `expf`, `logf`, `sinf` and `powf` actually do — so a width is
// only usable if the matching `f64xN` exists to widen into, and `wide` stops
// at `f64x8`.
